const http = require('http');
const https = require('https');
const url = require('url');
const { WebSocketServer, WebSocket } = require('ws');

const PORT = process.env.PORT || 10000;
// Set this to 'deeeep.io' or 'narrow.one' depending on what you are hosting
const TARGET_HOST = 'deeeep.io'; 

const server = http.createServer((req, res) => {
    if (req.url === '/ping') {
            res.writeHead(200, { 'Content-Type': 'text/plain' });
                    return res.end('pong');
                        }

                            let parsedUrl = url.parse(req.url);
                                let targetHost = TARGET_HOST;
                                    let targetPath = parsedUrl.path;

                                        if (targetPath.startsWith('/__proxy_domain/')) {
                                                const parts = targetPath.substring('/__proxy_domain/'.length).split('/');
                                                        if (parts.length > 0 && parts[0]) {
                                                                    targetHost = parts[0];
                                                                                targetPath = '/' + parts.slice(1).join('/');
                                                                                        }
                                                                                            }

                                                                                                const options = {
                                                                                                        hostname: targetHost,
                                                                                                                port: 443,
                                                                                                                        path: targetPath,
                                                                                                                                method: req.method,
                                                                                                                                        headers: { ...req.headers }
                                                                                                                                            };

                                                                                                                                                // Spoof legitimate client browser environments to clear security checks
                                                                                                                                                    delete options.headers['host'];
                                                                                                                                                        delete options.headers['origin'];
                                                                                                                                                            delete options.headers['referer'];
                                                                                                                                                                delete options.headers['accept-encoding']; // Prevent compressed binary corruption
                                                                                                                                                                    
                                                                                                                                                                        options.headers['host'] = targetHost;
                                                                                                                                                                            options.headers['origin'] = `https://${TARGET_HOST}`;
                                                                                                                                                                                options.headers['referer'] = `https://${TARGET_HOST}/`;
                                                                                                                                                                                    options.headers['user-agent'] = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36';

                                                                                                                                                                                        const proxyReq = https.request(options, (proxyRes) => {
                                                                                                                                                                                                const cleanHeaders = { ...proxyRes.headers };
                                                                                                                                                                                                        delete cleanHeaders['content-security-policy'];
                                                                                                                                                                                                                delete cleanHeaders['content-security-policy-report-only'];
                                                                                                                                                                                                                        
                                                                                                                                                                                                                                cleanHeaders['access-control-allow-origin'] = '*';
                                                                                                                                                                                                                                        cleanHeaders['access-control-allow-methods'] = '*';
                                                                                                                                                                                                                                                cleanHeaders['access-control-allow-headers'] = '*';

                                                                                                                                                                                                                                                        const contentType = cleanHeaders['content-type'] || '';
                                                                                                                                                                                                                                                                const isText = contentType.includes('javascript') || contentType.includes('html') || contentType.includes('json');

                                                                                                                                                                                                                                                                        if (isText) {
                                                                                                                                                                                                                                                                                    let body = [];
                                                                                                                                                                                                                                                                                                proxyRes.on('data', chunk => body.push(chunk));
                                                                                                                                                                                                                                                                                                            proxyRes.on('end', () => {
                                                                                                                                                                                                                                                                                                                            let text = Buffer.concat(body).toString('utf8');
                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                            // Advanced wildcard parser catches matchmakers and cross-origin scripts
                                                                                                                                                                                                                                                                                                                                                                            const domainRegex = /https?:\/\/([a-zA-Z0-9.-]+\.(?:narrow\.one|pelicanparty\.co|deeeep\.io|colyseus\\.dev|pubnub\.com))/g;
                                                                                                                                                                                                                                                                                                                                                                                            text = text.replace(domainRegex, (match, domain) => {
                                                                                                                                                                                                                                                                                                                                                                                                                return `/__proxy_domain/${domain}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                // Catch-all websocket pipeline interceptor
                                                                                                                                                                                                                                                                                                                                                                                                                                                                text = text.replace(/wss?:\/\/([a-zA-Z0-9.-]+)/g, (match, domain) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return `wss://${req.headers.host}/__proxy_ws/${domain}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const updatedBuffer = Buffer.from(text, 'utf8');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    cleanHeaders['content-length'] = updatedBuffer.length;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    res.writeHead(proxyRes.statusCode, cleanHeaders);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    res.end(updatedBuffer);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    res.writeHead(proxyRes.statusCode, cleanHeaders);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                proxyRes.pipe(res);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                proxyReq.on('error', (err) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!res.headersSent) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    res.writeHead(502, { 'Content-Type': 'text/plain' });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                res.end(`Proxy link dropping traffic: ${err.message}`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                req.pipe(proxyReq);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const wss = new WebSocketServer({ noServer: true });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                server.on('upgrade', (request, socket, head) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const pathname = url.parse(request.url).pathname;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        let targetWsHost = TARGET_HOST;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            let targetWsPath = pathname;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (pathname.startsWith('/__proxy_ws/')) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const parts = pathname.substring('/__proxy_ws/'.length).split('/');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (parts.length > 0 && parts[0]) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            targetWsHost = parts[0];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        targetWsPath = '/' + parts.slice(1).join('/');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        wss.handleUpgrade(request, socket, head, (ws) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const targetWsUrl = `wss://${targetWsHost}${targetWsPath}${url.parse(request.url).search || ''}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const remoteWs = new WebSocket(targetWsUrl, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            headers: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            'Origin': `https://${TARGET_HOST}`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ws.on('message', (message, isBinary) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (remoteWs.readyState === WebSocket.OPEN) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    remoteWs.send(message, { binary: isBinary });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                remoteWs.on('message', (message, isBinary) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (ws.readyState === WebSocket.OPEN) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ws.send(message, { binary: isBinary });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const closeChannels = () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    try { ws.close(); } catch(e){}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                try { remoteWs.close(); } catch(e){}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ws.on('close', closeChannels);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        remoteWs.on('close', closeChannels);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ws.on('error', closeChannels);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        remoteWs.on('error', closeChannels);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            server.listen(PORT, '0.0.0.0', () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                console.log(`Hardened Anti-Bot Spoofer online on port ${PORT}`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                